<?php
require __DIR__.'/../app/bootstrap.php';
require_permission('subscriptions.manage');
require_once __DIR__.'/../app/payments.php';
require_once __DIR__.'/../app/accounting.php';
$msg=$err=null;$admin=current_user();$adminId=(int)$admin['id'];
accounting_sync_invoice_statuses();
if(setting_bool('subscription_auto_expire',true)){try{db()->exec("UPDATE subscriptions SET status='expired' WHERE status='active' AND end_date<CURDATE()");}catch(Throwable $e){}}

function sub_rows(string $sql,array $params=[]): array {try{$q=db()->prepare($sql);$q->execute($params);return $q->fetchAll();}catch(Throwable $e){return [];}}
function sub_scalar(string $sql,array $params=[]): float {try{$q=db()->prepare($sql);$q->execute($params);return (float)($q->fetchColumn()?:0);}catch(Throwable $e){return 0;}}
function business_owner_id(int $businessId): int {$q=db()->prepare("SELECT owner_id FROM businesses WHERE id=? LIMIT 1");$q->execute([$businessId]);return (int)($q->fetchColumn()?:0);}

if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  csrf_check();$action=(string)($_POST['action']??'save_plan');$id=(int)($_POST['id']??0);
  if($action==='delete_plan'){
    $q=db()->prepare("SELECT COUNT(*) FROM subscriptions WHERE plan_id=?");$q->execute([$id]);
    if((int)$q->fetchColumn()>0)throw new RuntimeException('Plan has subscription history. Disable it instead.');
    db()->prepare("DELETE FROM subscription_plans WHERE id=?")->execute([$id]);$msg='Plan deleted.';
  }
  elseif($action==='save_plan'){
    $name=trim((string)($_POST['name']??''));$slug=strtolower(trim((string)($_POST['slug']??'')));$slug=preg_replace('/[^a-z0-9-]+/','-',$slug);
    $price=max(0,(float)($_POST['price']??0));$billing=(string)($_POST['billing_period']??'yearly');$status=isset($_POST['status'])?1:0;
    if($name===''||$slug==='')throw new RuntimeException('Plan name and slug are required.');
    if(!in_array($billing,['monthly','yearly','custom'],true))throw new RuntimeException('Invalid billing period.');
    $features=array_values(array_filter(array_map('trim',preg_split('/\r\n|\r|\n/',(string)($_POST['features_text']??'')))));
    if($id)db()->prepare("UPDATE subscription_plans SET name=?,slug=?,price=?,billing_period=?,features_json=?,status=? WHERE id=?")->execute([$name,$slug,$price,$billing,json_encode($features),$status,$id]);
    else{db()->prepare("INSERT INTO subscription_plans(name,slug,price,billing_period,features_json,status) VALUES(?,?,?,?,?,?)")->execute([$name,$slug,$price,$billing,json_encode($features),$status]);$id=(int)db()->lastInsertId();}
    db()->prepare("INSERT INTO subscription_plan_details(plan_id,duration_days,business_limit,featured_limit,ad_credit,description,features_text,approval_mode,recommended) VALUES(?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE duration_days=VALUES(duration_days),business_limit=VALUES(business_limit),featured_limit=VALUES(featured_limit),ad_credit=VALUES(ad_credit),description=VALUES(description),features_text=VALUES(features_text),approval_mode=VALUES(approval_mode),recommended=VALUES(recommended)")->execute([$id,max(1,(int)($_POST['duration_days']??365)),max(1,(int)($_POST['business_limit']??1)),max(0,(int)($_POST['featured_limit']??0)),max(0,(float)($_POST['ad_credit']??0)),trim((string)($_POST['description']??'')),trim((string)($_POST['features_text']??'')),in_array(($_POST['approval_mode']??'payment'),['payment','auto','manual'],true)?$_POST['approval_mode']:'payment',isset($_POST['recommended'])?1:0]);
    $msg='Subscription plan saved.';
  }
  elseif($action==='assign_subscription'){
    $businessId=(int)($_POST['business_id']??0);$planId=(int)($_POST['plan_id']??0);
    if(!$businessId||!$planId)throw new RuntimeException('Business and plan are required.');
    $q=db()->prepare("SELECT sp.*,COALESCE(spd.duration_days,365) duration_days FROM subscription_plans sp LEFT JOIN subscription_plan_details spd ON spd.plan_id=sp.id WHERE sp.id=? LIMIT 1");$q->execute([$planId]);$plan=$q->fetch();if(!$plan)throw new RuntimeException('Plan not found.');
    $amount=max(0,(float)($_POST['subscription_amount']??$plan['price']));$taxPercent=max(0,min(100,(float)setting('subscription_tax_percent','0')));$taxAmount=round($amount*$taxPercent/100,2);$start=(string)($_POST['start_date']??'')?:date('Y-m-d');$end=(string)($_POST['end_date']??'')?:date('Y-m-d',strtotime($start.' +'.max(1,(int)$plan['duration_days']).' days'));
    if(strtotime($end)<=strtotime($start))throw new RuntimeException('End date must be after start date.');
    $accessStatus=in_array(($_POST['subscription_status']??'pending'),['pending','active','expired','cancelled','suspended'],true)?$_POST['subscription_status']:'pending';
    $billing=(string)($_POST['billing_workflow']??'invoice');
    db()->beginTransaction();
    try{
      db()->prepare("INSERT INTO subscriptions(business_id,plan_id,start_date,end_date,status,amount) VALUES(?,?,?,?,?,?)")->execute([$businessId,$planId,$start,$end,$accessStatus,$amount]);$subscriptionId=(int)db()->lastInsertId();
      if($billing==='waived' || $amount<=0){
        $invoice=accounting_create_subscription_invoice($subscriptionId,$businessId,$planId,$amount,null,$_POST['due_date']?:null,'Admin assigned subscription',$adminId,0,$taxAmount);
        if($amount>0)accounting_mark_invoice_waived((int)$invoice['id'],$adminId);
        db()->prepare("UPDATE subscriptions SET status='active' WHERE id=?")->execute([$subscriptionId]);
      }else{
        $ownerId=business_owner_id($businessId);if(!$ownerId)throw new RuntimeException('Selected business does not have a valid owner account.');
        $orderId=create_payment_order($ownerId,$amount,'subscription',$businessId,$planId,null,'none',['subscription_id'=>$subscriptionId,'created_from'=>'admin_plans']);
        $invoice=accounting_create_subscription_invoice($subscriptionId,$businessId,$planId,$amount,$orderId,$_POST['due_date']?:null,'Subscription assigned from admin',$adminId,0,$taxAmount);
        if($billing==='paid'){
          $gateway=(string)($_POST['receipt_gateway']??'cash');mark_payment_order_paid($orderId,$gateway,'ADMIN-'.strtoupper(bin2hex(random_bytes(3))),['admin_subscription_assignment'=>true],$adminId);
        }
      }
      db()->commit();$msg='Subscription assigned with accounts/invoice entry.';
    }catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
  }
  elseif($action==='invoice_paid'){
    $invoice=subscription_invoice((int)$_POST['invoice_id']);if(!$invoice)throw new RuntimeException('Invoice not found.');if(!$invoice['payment_order_id'])throw new RuntimeException('Invoice has no linked payment order.');
    mark_payment_order_paid((int)$invoice['payment_order_id'],(string)($_POST['gateway']??'cash'),'ADMIN-RECEIPT-'.strtoupper(bin2hex(random_bytes(3))),['approved_from_subscription_dashboard'=>true],$adminId);$msg='Invoice payment posted to ledger.';
  }
  elseif($action==='invoice_waive'){accounting_mark_invoice_waived((int)$_POST['invoice_id'],$adminId);$msg='Invoice waived and ledger reversed.';}
  elseif($action==='invoice_void'){accounting_void_invoice((int)$_POST['invoice_id'],$adminId);$msg='Invoice voided and ledger reversed.';}
 }catch(Throwable $e){$err=$e->getMessage();}
}

$edit=null;if(isset($_GET['edit'])){$q=db()->prepare("SELECT sp.*,spd.* FROM subscription_plans sp LEFT JOIN subscription_plan_details spd ON spd.plan_id=sp.id WHERE sp.id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}
$plans=sub_rows("SELECT sp.*,COALESCE(spd.duration_days,365) duration_days,COALESCE(spd.business_limit,1) business_limit,COALESCE(spd.featured_limit,0) featured_limit,COALESCE(spd.ad_credit,0) ad_credit,spd.description,spd.features_text,spd.approval_mode,COALESCE(spd.recommended,0) recommended,(SELECT COUNT(*) FROM subscriptions s WHERE s.plan_id=sp.id) subscription_count,(SELECT COUNT(*) FROM subscriptions s WHERE s.plan_id=sp.id AND s.status='active' AND s.end_date>=CURDATE()) active_count,(SELECT COALESCE(SUM(i.total),0) FROM subscription_invoices i WHERE i.plan_id=sp.id AND i.status NOT IN ('void','waived')) billed_total FROM subscription_plans sp LEFT JOIN subscription_plan_details spd ON spd.plan_id=sp.id ORDER BY sp.price,sp.id");
$businesses=sub_rows("SELECT id,name FROM businesses WHERE status=1 ORDER BY name");
$subs=sub_rows("SELECT s.*,b.name business_name,sp.name plan_name,DATEDIFF(s.end_date,CURDATE()) days_left FROM subscriptions s JOIN businesses b ON b.id=s.business_id JOIN subscription_plans sp ON sp.id=s.plan_id ORDER BY s.id DESC LIMIT 250");
$invoices=subscription_invoices('',null,250);
$activeSubs=(int)sub_scalar("SELECT COUNT(*) FROM subscriptions WHERE status='active' AND end_date>=CURDATE()");
$totalSubs=(int)sub_scalar("SELECT COUNT(*) FROM subscriptions");
$reminderDays=max(1,min(180,setting_int('subscription_expiry_reminder_days',30)));$expiring=(int)sub_scalar("SELECT COUNT(*) FROM subscriptions WHERE status='active' AND end_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL ".$reminderDays." DAY)");
$receivable=sub_scalar("SELECT COALESCE(SUM(total-paid_amount),0) FROM subscription_invoices WHERE status IN ('unpaid','partial','overdue')");
$paidRevenue=sub_scalar("SELECT COALESCE(SUM(l.credit-l.debit),0) FROM accounting_journal_lines l JOIN accounting_accounts a ON a.id=l.account_id JOIN accounting_journals j ON j.id=l.journal_id WHERE a.system_key='subscription_revenue' AND j.status='posted'");
$mrr=sub_scalar("SELECT COALESCE(SUM(s.amount/GREATEST(COALESCE(spd.duration_days,365),1)*30),0) FROM subscriptions s LEFT JOIN subscription_plan_details spd ON spd.plan_id=s.plan_id WHERE s.status='active' AND s.end_date>=CURDATE()");
$arr=$mrr*12;
$renewalRate=$totalSubs?round($activeSubs/$totalSubs*100,1):0;
$trend=[];for($i=5;$i>=0;$i--){$ts=strtotime("-{$i} months");$ym=date('Y-m',$ts);$trend[$ym]=['label'=>date('M',$ts),'subs'=>0,'billed'=>0];}
foreach(sub_rows("SELECT DATE_FORMAT(created_at,'%Y-%m') ym,COUNT(*) c FROM subscriptions WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 5 MONTH) GROUP BY DATE_FORMAT(created_at,'%Y-%m')") as $r)if(isset($trend[$r['ym']]))$trend[$r['ym']]['subs']=(int)$r['c'];
foreach(sub_rows("SELECT DATE_FORMAT(created_at,'%Y-%m') ym,COALESCE(SUM(total),0) total FROM subscription_invoices WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 5 MONTH) AND status NOT IN ('void','waived') GROUP BY DATE_FORMAT(created_at,'%Y-%m')") as $r)if(isset($trend[$r['ym']]))$trend[$r['ym']]['billed']=(float)$r['total'];
$tab=in_array(($_GET['tab']??''),['dashboard','plans','subscriptions','invoices','assign'],true)?$_GET['tab']:($edit?'plans':'dashboard');

require __DIR__.'/../app/layout.php';page_start('Subscriptions & Revenue',true);
?>
