<div class="sub-stat-grid"><article><i>S</i><div><b><?=e($activeSubs)?></b><span>Active Subscriptions</span><small><?=e(number_format($renewalRate,1))?>% active ratio</small></div></article><article><i>₨</i><div><b><?=e(number_format($mrr,0))?></b><span>MRR</span><small>Rs <?=e(number_format($arr,0))?> projected ARR</small></div></article><article><i>R</i><div><b><?=e(number_format($paidRevenue,0))?></b><span>Recognized Revenue</span><small>Ledger subscription revenue</small></div></article><article><i>AR</i><div><b><?=e(number_format($receivable,0))?></b><span>Receivables</span><small>Outstanding invoices</small></div></article><article><i>!</i><div><b><?=e($expiring)?></b><span>Expiring ≤ 30 Days</span><small>Renewal follow-up required</small></div></article></div>
<div class="sub-dashboard-grid"><section class="card"><div class="sub-panel-head"><div><h3>6-Month Subscription Growth</h3><span>New subscriptions and billed revenue.</span></div></div><div class="sub-chart"><?php $mx=max(1,...array_column($trend,'subs'));foreach($trend as $m):$h=max(8,(int)round($m['subs']/$mx*165));?><div><div class="sub-bar" style="height:<?=$h?>px"><span><?=e($m['subs'])?></span></div><b><?=e($m['label'])?></b><small>Rs <?=e(number_format($m['billed'],0))?></small></div><?php endforeach;?></div></section><section class="card"><div class="sub-panel-head"><div><h3>Plan Performance</h3><span>Active users and billed value by plan.</span></div></div><div class="plan-performance"><?php foreach($plans as $p):?><div><span><b><?=e($p['name'])?></b><small>Rs <?=e(number_format((float)$p['price'],0))?> · <?=e($p['duration_days'])?> days</small></span><strong><?=e($p['active_count'])?></strong><em>Rs <?=e(number_format((float)$p['billed_total'],0))?></em></div><?php endforeach;?></div></section></div>
<div class="sub-dashboard-grid"><section class="card"><div class="sub-panel-head"><div><h3>Upcoming Renewals</h3><span>Subscriptions ending in the next 30 days.</span></div><a href="?tab=subscriptions">All subscriptions</a></div><div class="renewal-list"><?php $shown=0;foreach($subs as $s):if($s['status']!=='active'||$s['days_left']<0||$s['days_left']>$reminderDays)continue;$shown++;?><div><span><b><?=e($s['business_name'])?></b><small><?=e($s['plan_name'])?> · ends <?=e(date('d M Y',strtotime($s['end_date'])))?></small></span><strong><?=e($s['days_left'])?>d</strong><a href="?tab=assign">Renew</a></div><?php if($shown>=7)break;endforeach;?><?php if(!$shown):?><div class="empty-state">No subscriptions expiring in the next 30 days.</div><?php endif;?></div></section><section class="card"><div class="sub-panel-head"><div><h3>Outstanding Invoices</h3><span>Subscription accounts receivable.</span></div><a href="?tab=invoices">Invoice center</a></div><div class="invoice-mini-list"><?php $shown=0;foreach($invoices as $i):if(!in_array($i['status'],['unpaid','partial','overdue'],true))continue;$shown++;?><div><span><b><?=e($i['invoice_no'])?></b><small><?=e($i['business_name'])?> · due <?=e(date('d M',strtotime($i['due_date'])))?></small></span><strong>Rs <?=e(number_format((float)$i['total']-(float)$i['paid_amount'],0))?></strong><em class="<?=e($i['status'])?>"><?=e($i['status'])?></em></div><?php if($shown>=7)break;endforeach;?><?php if(!$shown):?><div class="empty-state">No outstanding invoices.</div><?php endif;?></div></section></div>

