)?></textarea><label>Features — one per line</label><textarea class="input" rows="5" name="features_text"><?=e($edit['features_text']??'')?></textarea><div class="plan-checks"><label><input type="checkbox" name="recommended" <?=($edit['recommended']??0)?'checked':''?>> Recommended</label><label><input type="checkbox" name="status" <?=($edit['status']??1)?'checked':''?>> Active</label></div><button class="btn"><?=$edit?'Update Plan':'Create Plan'?></button></form></aside></div>

