ry?')"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="invoice_waive"><input type="hidden" name="invoice_id" value="<?=e($i['id'])?>"><button class="btn ghost">Waive</button></form><form method="post" onsubmit="return confirm('Void this invoice?')"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="invoice_void"><input type="hidden" name="invoice_id" value="<?=e($i['id'])?>"><button class="btn danger">Void</button></form><?php endif;?></div></td></tr><?php endforeach;?></table></div></section>

<?php else:?>
<div class="assign-layout"><section class="card"><div class="sub-panel-head"><div><h3>Assign / Renew Subscription</h3><span>Create subscription access and its financial invoice together.</span></div></div><form method="post" id="assignSubscriptionForm"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="assign_subscription"><div class="sub-form-grid"><div><label>Business</label><select class="input" name="business_id" required><option value="">Select business</option><?php foreach($businesses as $b):?><option value="<?=e($b['id'])?>"><?=e($b['name'])?></option><?php endforeach;?></select></div><div><label>Plan</label><select class="input" name="plan_id" id="assignPlan" required><option value="">Select plan</option><?php foreach($plans as $p):?><option value="<?=e($p['id'])?>" data-price="<?=e($p['price'])?>" data-days="<?=e($p['duration_days'])?>"><?=e($p['name'])?> · Rs <?=e(number_format((float)$p['price'],0))?></option><?php endforeach;?></select></div><div><label>Amount PKR</label><input class="input" type="number" min="0" step="0.01" name="subscription_amount" id="assignAmount" value="0"></div><div><label>Access Status</label><select class="input" name="subscription_status"><option value="pending">Pending until payment</option><option value="active">Active immediately</option><option value="suspended">Suspended</option></select></div><div><label>Start Date</label><input class="input" type="date" name="start_date" id="assignStart" value="<?=e(date('Y-m-d'))?>"></div><div><label>End Date</label><input class="input" type="date" name="end_date" id="assignEnd"></div><div><label>Invoice Due Date</label><input class="input" type="date" name="due_date" value="<?=e(date('Y-m-d',strtotime('+'.setting_int('subscription_invoice_due_days',7).' days')))?>"></div><div><label>Billing Workflow</label><select class="input" name="billing_workflow" id="billingWorkflow"><option value="invoice">Issue Invoice — Unpaid</option><option value="paid">Issue Invoice — Receive Payment Now</option><option value="waived">Waived / Complimentary</option></select></div><div id="receiptGatewayWrap" style="display:none"><label>Receipt Account</label><select class="input" name="receipt_gateway"><option value="cash">Cash</option><option value="bank_transfer">Bank / Raast</option><option value="jazzcash">JazzCash</option><option value="easypaisa">Easypaisa</option><option value="payfast">PayFast</option></select></div></div><div class="billing-note"><b>Accounting flow:</b> issuing an invoice posts <strong>Dr Accounts Receivable / Cr Subscription Revenue</strong>. Receiving payment posts <strong>Dr Cash/Bank / Cr Accounts Receivable</strong>.</div><button class="btn">Assign Subscription & Create Billing</button></form></section><aside class="card assign-summary"><h3>Billing Summary</h3><div><span>Plan</span><b id="summaryPlan">—</b></div><div><span>Subscription Amount</span><b id="summaryAmount">Rs 0</b></div><div><span>Duration</span><b id="summaryDays">—</b></div><div><span>Ledger</span><b>Automatic</b></div><a class="btn ghost" href="/admin/accounts.php">Open Accounts Ledger</a></aside></div>
<script>
(function(){const plan=document.getElementById('assignPlan'),amount=document.getElementById('assignAmount'),start=document.getElementById('assignStart'),end=document.getElementById('assignEnd'),flow=document.getElementById('billingWorkflow'),wrap=document.getElementById('receiptGatewayWrap'),sp=document.getElementById('summaryPlan'),sa=document.getElementById('summaryAmount'),sd=document.getElementById('summaryDays');function sync(){const o=plan.options[plan.selectedIndex];const price=Number(o?.dataset?.price||0),days=Number(o?.dataset?.days||0);if(plan.value&&Number(amount.value)===0)amount.value=price.toFixed(2);sp.textContent=plan.value?o.text.split(' · ')[0]:'—';sa.textContent='Rs '+Number(amount.value||0).toLocaleString();sd.textContent=days?days+' days':'—';if(start.value&&days){const d=new Date(start.value+'T00:00:00');d.setDate(d.getDate()+days);end.value=d.toISOString().slice(0,10)}}plan?.addEventListener('change',sync);amount?.addEventListener('input',sync);start?.addEventListener('change',sync);flow?.addEventListener('change',()=>wrap.style.display=flow.value==='paid'?'block':'none');sync()})();
</script>
<?php endif;?>
